1|static json_t *build_nested_array(int depth) {
2|    json_t *json = json_array();
3|    int i;
4|
5|    for (i = 1; i < depth; i++) {
6|        json_t *outer = json_array();
7|        json_array_append_new(outer, json);
8|        json = outer;
9|    }
10|
11|    return json;
12|}
