14|static void max_depth() {
15|    json_t *json;
16|    char *result;
17|
18|    /* A structure nested exactly to the limit must still serialize. */
19|    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
20|    result = json_dumps(json, 0);
21|    if (!result)
22|        fail("json_dumps failed for a structure within the depth limit");
23|    free(result);
24|    json_decref(json);
25|
26|    /* A structure nested deeper than the limit must fail cleanly rather
27|       than overflow the stack. */
28|    json = build_nested_array(JSON_PARSER_MAX_DEPTH + 100);
29|    if (json_dumps(json, 0) != NULL)
30|        fail("json_dumps didn't fail for a too deeply nested structure");
31|    json_decref(json);
32|}

943|json_t *json_loadb(const char *buffer, size_t buflen, size_t flags, json_error_t *error) {
944|    lex_t lex;
945|    json_t *result;
946|    buffer_data_t stream_data;
947|
948|    jsonp_error_init(error, "<buffer>");
949|
950|    if (buffer == NULL) {
951|        error_set(error, NULL, json_error_invalid_argument, "wrong arguments");
952|        return NULL;
953|    }
954|
955|    stream_data.data = buffer;
956|    stream_data.pos = 0;
957|    stream_data.len = buflen;
958|
959|    if (lex_init(&lex, buffer_get, flags, (void *)&stream_data))
960|        return NULL;
961|
962|    result = parse_json(&lex, flags, error);
963|
964|    lex_close(&lex);
965|    return result;
966|}

