801|            break;
802|        }
803|
804|        case TOKEN_INTEGER: {
805|            json = json_integer(lex->value.integer);
806|            break;
807|        }
808|
809|        case TOKEN_REAL: {
810|            json = json_real(lex->value.real);
811|            break;
812|        }
813|
814|        case TOKEN_TRUE:
815|            json = json_true();
816|            break;
817|
818|        case TOKEN_FALSE:
819|            json = json_false();
820|            break;
821|
822|        case TOKEN_NULL:
823|            json = json_null();
824|            break;
825|
826|        case '{':
