853|    lex->depth = 0;
854|
855|    lex_scan(lex, error);
856|    if (!(flags & JSON_DECODE_ANY)) {
857|        if (lex->token != '[' && lex->token != '{') {
858|            error_set(error, lex, json_error_invalid_syntax, "'[' or '{' expected");
859|            return NULL;
860|        }
861|    }
862|
863|    result = parse_value(lex, flags, error);
864|    if (!result)
