232|static int lex_get_save(lex_t *lex, json_error_t *error) {
233|    int c = stream_get(&lex->stream, error);
234|    if (c != STREAM_STATE_EOF && c != STREAM_STATE_ERROR)
235|        lex_save(lex, c);
236|    return c;
